import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"界面模板","description":"","frontmatter":{},"headers":[],"relativePath":"modules/station/gui.md","filePath":"modules/station/gui.md","lastUpdated":0}`),a={name:`modules/station/gui.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="界面模板" tabindex="-1">界面模板 <a class="header-anchor" href="#界面模板" aria-label="Permalink to “界面模板”">​</a></h1><p>EmakiStation 有四份界面模板，放在 <code>plugins/EmakiStation/gui/</code> 下。</p><table tabindex="0"><thead><tr><th>模板</th><th>对应界面</th><th>工作站配置键</th></tr></thead><tbody><tr><td><code>station_catalog.yml</code></td><td>配方目录页（第一页）</td><td><code>layout</code></td></tr><tr><td><code>station_preview.yml</code></td><td>材料预览页（第二页）</td><td><code>preview_layout</code></td></tr><tr><td><code>station_queue.yml</code></td><td>合成队列页（第三页）</td><td><code>queue_layout</code></td></tr><tr><td><code>station_dismantle.yml</code></td><td>分解界面</td><td>分解站的 <code>layout</code></td></tr></tbody></table><p>前三页构成合成侧的三页结构：目录页左键直接提交、右键进入材料预览；预览页确认提交；队列页查看、取消、领取与购买队列位。分解界面独立，由 <code>/emakistation dismantle &lt;工作站&gt;</code> 进入。</p><h2 id="槽位必须显式写-type" tabindex="-1">槽位必须显式写 <code>type</code> <a class="header-anchor" href="#槽位必须显式写-type" aria-label="Permalink to “槽位必须显式写 type”">​</a></h2><p>EmakiStation 的槽位<strong>必须显式写 <code>type</code></strong>。CoreLib 的模板解析器只会为少数 Forge 专用键名自动推断类型，自定义键名不写 <code>type</code> 就只是纯装饰格。</p><p>判定顺序是「先看 <code>type</code>，为空再看槽位键名」，因此只有键名恰好等于下方类型名时才可省略 <code>type</code>。</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  recipe_list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">11</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;recipe_list&quot;</span></span></code></pre></div><h2 id="配方目录页可用类型" tabindex="-1">配方目录页可用类型 <a class="header-anchor" href="#配方目录页可用类型" aria-label="Permalink to “配方目录页可用类型”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>作用</th></tr></thead><tbody><tr><td><code>recipe_list</code></td><td>列出配方。<strong>必需</strong>（缺失时布局校验失败），否则布局校验不通过。</td></tr><tr><td><code>queue_open</code></td><td>打开合成队列页。</td></tr><tr><td><code>batch_multiplier</code></td><td>循环切换倍率，左键递增、右键递减。</td></tr><tr><td><code>output_toggle</code></td><td>切换产物去向。</td></tr><tr><td><code>prev_page</code> / <code>next_page</code> / <code>page_info</code></td><td>翻页。</td></tr><tr><td><code>close</code></td><td>关闭界面。</td></tr></tbody></table><p>本页<strong>没有</strong> input 槽。玩家不放材料进界面，材料在提交时直接从背包与仓库合并扣除。</p><p>目录页的点击行为：左键点条目直接按当前倍率提交；右键进入材料预览；未解锁（<code>display_condition</code> 不满足）的条目点击无反应。</p><h2 id="材料预览页可用类型" tabindex="-1">材料预览页可用类型 <a class="header-anchor" href="#材料预览页可用类型" aria-label="Permalink to “材料预览页可用类型”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>作用</th></tr></thead><tbody><tr><td><code>material_list</code></td><td>列出所选配方的材料需求。<strong>必需</strong>。</td></tr><tr><td><code>recipe_display</code></td><td>显示当前预览的配方。</td></tr><tr><td><code>cost_display</code></td><td>显示货币成本与玩家余额。</td></tr><tr><td><code>max_craftable</code></td><td>显示按材料与余额最多能做几次，点击直接拉满。</td></tr><tr><td><code>batch_multiplier</code></td><td>循环切换倍率。</td></tr><tr><td><code>confirm</code></td><td>提交。</td></tr><tr><td><code>back</code></td><td>返回目录页，会停在原来那一页。</td></tr><tr><td><code>prev_page</code> / <code>next_page</code> / <code>page_info</code></td><td>材料列表翻页。</td></tr><tr><td><code>close</code></td><td>关闭界面。</td></tr></tbody></table><p>本页只读，不接受放入物品。</p><p>倍率按钮的循环档位固定为 <code>1 → 10 → 64 → 1000</code>（左键递增、右键递减，到顶回绕）。<code>max_craftable</code> 会按材料与余额算出上限并<strong>直接设为当前倍率</strong>。</p><h3 id="材料数量的显示规则" tabindex="-1">材料数量的显示规则 <a class="header-anchor" href="#材料数量的显示规则" aria-label="Permalink to “材料数量的显示规则”">​</a></h3><table tabindex="0"><thead><tr><th>需求量</th><th>显示方式</th></tr></thead><tbody><tr><td>≤ 99</td><td>图标上带真实数字，客户端直接画出来。</td></tr><tr><td>≥ 100</td><td>图标数量固定为 1，不画数字，真实数量只出现在 lore 的 <code>%required_exact%</code>。</td></tr></tbody></table><p>因此 lore 里务必保留 <code>%required_exact%</code>，否则大额需求玩家将无从得知。</p><p>65~99 超过多数物品的自然堆叠上限，插件会临时抬高被渲染图标的 <code>max_stack_size</code> 组件。这个改动只作用于界面里的展示图标，永远不会交给玩家。</p><h2 id="合成队列页可用类型" tabindex="-1">合成队列页可用类型 <a class="header-anchor" href="#合成队列页可用类型" aria-label="Permalink to “合成队列页可用类型”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>作用</th></tr></thead><tbody><tr><td><code>queue_view</code></td><td>列出队列条目。<strong>必需</strong>。</td></tr><tr><td><code>capacity_display</code></td><td>显示已用 / 上限，以及上限的来源。</td></tr><tr><td><code>queue_purchase</code></td><td>购买额外队列位，左键买 1 个，Shift 买一整批。</td></tr><tr><td><code>claim_all</code></td><td>领取全部待领取产物。</td></tr><tr><td><code>back</code></td><td>返回目录页，会停在原来那一页。</td></tr><tr><td><code>prev_page</code> / <code>next_page</code> / <code>page_info</code></td><td>队列翻页。</td></tr><tr><td><code>close</code></td><td>关闭界面。</td></tr></tbody></table><p>本页只读，不接受放入物品。</p><p>队列条目的点击行为：<code>PENDING_CLAIM</code> 条目点击等同于「领取全部」；其余条目点击即取消该条目。<code>queue_purchase</code> 的「买一整批」取批量选项里的最大值（见<a href="./queue-costs.html">付费队列位</a>）。</p><h2 id="分解界面可用类型" tabindex="-1">分解界面可用类型 <a class="header-anchor" href="#分解界面可用类型" aria-label="Permalink to “分解界面可用类型”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>作用</th></tr></thead><tbody><tr><td><code>dismantle_input</code></td><td>展示当前选中配方的输入物品图标（只读预览，不放物品）。</td></tr><tr><td><code>dismantle_item_display</code></td><td>同 <code>dismantle_input</code>，别名。</td></tr><tr><td><code>dismantle_rolls_display</code></td><td>显示投掷次数范围（<code>%rolls_min%</code> / <code>%rolls_max%</code>）。</td></tr><tr><td><code>dismantle_output_list</code></td><td>分解产物列表，多格分页，含 <code>pool_entry</code> / <code>rolled_output</code> 虚拟物品。</td></tr><tr><td><code>dismantle_confirm</code></td><td>确认执行分解，或领取已投掷产物。</td></tr><tr><td><code>prev_page</code> / <code>next_page</code> / <code>page_info</code></td><td>产物列表翻页。</td></tr><tr><td><code>back</code></td><td>返回目录页。</td></tr><tr><td><code>close</code></td><td>关闭界面。</td></tr></tbody></table><p>分页控件同时服务于「预览概率池」和「已投掷产物」两种列表，翻页上限按当前所处状态切换。</p><h2 id="占位符全集" tabindex="-1">占位符全集 <a class="header-anchor" href="#占位符全集" aria-label="Permalink to “占位符全集”">​</a></h2><p>界面模板里的 <code>%...%</code> 是<strong>模板内部占位符</strong>，由 EmakiStation 渲染，与 PlaceholderAPI 无关（PAPI 变量只在条件表达式文本里会被透传解析）。</p><h3 id="标题占位符-模板顶层-title" tabindex="-1">标题占位符（模板顶层 <code>title</code>） <a class="header-anchor" href="#标题占位符-模板顶层-title" aria-label="Permalink to “标题占位符（模板顶层 title）”">​</a></h3><table tabindex="0"><thead><tr><th>占位符</th><th>配方目录页</th><th>材料预览页</th><th>合成队列页</th><th>分解界面</th></tr></thead><tbody><tr><td><code>%station_name%</code></td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>%station%</code></td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>%player%</code></td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>%recipe%</code></td><td>—</td><td>✓</td><td>—</td><td>✓</td></tr><tr><td><code>%recipe_name%</code></td><td>—</td><td>✓</td><td>—</td><td>✓</td></tr><tr><td><code>%page%</code></td><td>✓</td><td>—</td><td>—</td><td>—</td></tr><tr><td><code>%pages%</code></td><td>✓</td><td>—</td><td>—</td><td>—</td></tr><tr><td><code>%used%</code> / <code>%max%</code></td><td>—</td><td>—</td><td>✓</td><td>—</td></tr></tbody></table><p>目录页标题里的 <code>%pages%</code> 取的是<strong>配方条目总数</strong>（源码如此），不是总页数；需要真实总页数请用槽位 <code>page_info</code>。</p><h3 id="目录页槽位占位符" tabindex="-1">目录页槽位占位符 <a class="header-anchor" href="#目录页槽位占位符" aria-label="Permalink to “目录页槽位占位符”">​</a></h3><table tabindex="0"><thead><tr><th>槽位类型</th><th>可用占位符</th></tr></thead><tbody><tr><td><code>recipe_list</code></td><td><code>%recipe%</code>、<code>%recipe_name%</code>、<code>%result_name%</code>、<code>%result_amount%</code>、<code>%duration%</code>、<code>%batch%</code>、<code>%index%</code>、<code>%page%</code>、<code>%pages%</code>、<code>%conditions%</code>、<code>%costs%</code>、<code>%materials%</code>；未解锁条目额外有 <code>%lock_reason%</code></td></tr><tr><td><code>batch_multiplier</code></td><td><code>%batch%</code>、<code>%batch_exact%</code></td></tr><tr><td><code>output_toggle</code></td><td><code>%output%</code>、<code>%output_state%</code></td></tr><tr><td><code>page_info</code> / <code>prev_page</code> / <code>next_page</code></td><td><code>%page%</code>、<code>%pages%</code>、<code>%total%</code></td></tr></tbody></table><p><code>%conditions%</code> / <code>%costs%</code> / <code>%materials%</code> 是整行展开占位符：写在 lore 时必须独占一行，CoreLib 会把该行按条目数展开成多行。写成 <code>材料: %materials%</code> 不会展开。</p><h3 id="预览页槽位占位符" tabindex="-1">预览页槽位占位符 <a class="header-anchor" href="#预览页槽位占位符" aria-label="Permalink to “预览页槽位占位符”">​</a></h3><table tabindex="0"><thead><tr><th>槽位类型</th><th>可用占位符</th></tr></thead><tbody><tr><td><code>material_list</code></td><td><code>%material%</code>、<code>%material_id%</code>、<code>%requirement_id%</code>、<code>%count_key%</code>、<code>%required%</code>、<code>%required_exact%</code>、<code>%owned%</code>、<code>%owned_exact%</code>、<code>%satisfied%</code>、<code>%consumed%</code>、<code>%alternatives%</code>、<code>%index%</code>、<code>%page%</code>、<code>%pages%</code></td></tr><tr><td><code>recipe_display</code></td><td><code>%recipe%</code>、<code>%recipe_name%</code>、<code>%result_name%</code>、<code>%result_amount%</code>、<code>%duration%</code>、<code>%batch%</code></td></tr><tr><td><code>cost_display</code></td><td><code>%cost%</code>、<code>%cost_exact%</code>、<code>%currency%</code>、<code>%balance%</code>、<code>%affordable%</code>、<code>%free%</code></td></tr><tr><td><code>max_craftable</code></td><td><code>%max%</code>、<code>%max_exact%</code>、<code>%batch%</code></td></tr><tr><td><code>batch_multiplier</code></td><td><code>%batch%</code>、<code>%batch_exact%</code></td></tr><tr><td><code>confirm</code></td><td><code>%recipe%</code>、<code>%recipe_name%</code>、<code>%batch%</code>；被拦下时（改用 <code>confirm_blocked</code> 虚拟物品）为 <code>%block_reason%</code>、<code>%block_text%</code></td></tr><tr><td><code>page_info</code> / <code>prev_page</code> / <code>next_page</code></td><td><code>%page%</code>、<code>%pages%</code>、<code>%total%</code></td></tr></tbody></table><h3 id="队列页槽位占位符" tabindex="-1">队列页槽位占位符 <a class="header-anchor" href="#队列页槽位占位符" aria-label="Permalink to “队列页槽位占位符”">​</a></h3><table tabindex="0"><thead><tr><th>槽位类型</th><th>可用占位符</th></tr></thead><tbody><tr><td><code>queue_view</code></td><td>普通条目：<code>%index%</code>、<code>%recipe%</code>、<code>%batch%</code>、<code>%state%</code>、<code>%remaining%</code>、<code>%cost%</code>、<code>%currency%</code>、<code>%page%</code>、<code>%pages%</code>（待领取条目改用 <code>queue_pending</code> 虚拟物品，占位符集合相同）</td></tr><tr><td><code>capacity_display</code></td><td><code>%used%</code>、<code>%max%</code>、<code>%purchased%</code>、<code>%base%</code>、<code>%ceiling%</code>、<code>%pending%</code></td></tr><tr><td><code>queue_purchase</code></td><td>可购买时：<code>%slots%</code>、<code>%cost%</code>、<code>%currency%</code>、<code>%items%</code>；不可购买时（改用 <code>purchase_unavailable</code> 虚拟物品）：<code>%reason%</code>、<code>%reason_text%</code></td></tr><tr><td><code>claim_all</code></td><td><code>%pending%</code></td></tr><tr><td><code>page_info</code> / <code>prev_page</code> / <code>next_page</code></td><td><code>%page%</code>、<code>%pages%</code>、<code>%total%</code></td></tr></tbody></table><h3 id="分解界面槽位占位符" tabindex="-1">分解界面槽位占位符 <a class="header-anchor" href="#分解界面槽位占位符" aria-label="Permalink to “分解界面槽位占位符”">​</a></h3><table tabindex="0"><thead><tr><th>槽位类型</th><th>可用占位符</th></tr></thead><tbody><tr><td><code>dismantle_input</code> / <code>dismantle_item_display</code></td><td><code>%recipe%</code>、<code>%recipe_name%</code>、<code>%input%</code>（没有匹配配方时改用 <code>no_recipe</code> 虚拟物品）</td></tr><tr><td><code>dismantle_rolls_display</code></td><td><code>%rolls_min%</code>、<code>%rolls_max%</code>、<code>%recipe_name%</code></td></tr><tr><td><code>dismantle_output_list</code></td><td>概率池条目：<code>%item%</code>、<code>%amount_min%</code>、<code>%amount_max%</code>、<code>%weight%</code>、<code>%chance%</code>、<code>%index%</code>、<code>%page%</code>、<code>%pages%</code>；已投掷产物：<code>%item%</code>、<code>%amount%</code>、<code>%amount_exact%</code>、<code>%index%</code>、<code>%total%</code></td></tr><tr><td><code>dismantle_confirm</code></td><td>未投掷：<code>%recipe%</code>、<code>%recipe_name%</code>；已投掷（改用 <code>dismantle_claim</code> 虚拟物品）：<code>%recipe_name%</code>、<code>%output_count%</code></td></tr><tr><td><code>page_info</code> / <code>prev_page</code> / <code>next_page</code></td><td><code>%page%</code>、<code>%pages%</code>、<code>%total%</code></td></tr></tbody></table><p><code>%chance%</code> 是按权重换算的百分比（保留一位小数），<code>%weight%</code> 是原始权重。</p><h2 id="virtual-items-与-texts" tabindex="-1"><code>virtual_items</code> 与 <code>texts</code> <a class="header-anchor" href="#virtual-items-与-texts" aria-label="Permalink to “virtual_items 与 texts”">​</a></h2><p>四份模板都有 <code>virtual_items</code> 段，用于定义列表项的图标形态：</p><table tabindex="0"><thead><tr><th>模板</th><th>已使用的 <code>virtual_items</code> 键</th></tr></thead><tbody><tr><td><code>station_catalog.yml</code></td><td><code>recipe_entry</code>、<code>recipe_locked</code></td></tr><tr><td><code>station_preview.yml</code></td><td><code>material_satisfied</code>、<code>material_missing</code>、<code>confirm_blocked</code></td></tr><tr><td><code>station_queue.yml</code></td><td><code>queue_entry</code>、<code>queue_pending</code>、<code>purchase_unavailable</code></td></tr><tr><td><code>station_dismantle.yml</code></td><td><code>no_recipe</code>、<code>dismantle_input</code>、<code>pool_entry</code>、<code>rolled_output</code>、<code>dismantle_claim</code></td></tr></tbody></table><p>这些键缺失时会回退到内置图标与文案（例如目录未解锁条目回退为灰色染料、确认被拦下回退为屏障）。前三份合成模板还有 <code>texts</code> 段，用于配置行文本片段：目录页的 <code>texts.recipe.*</code> 与 <code>texts.output_state.*</code>、预览页的 <code>texts.block_reason.*</code> 与 <code>texts.output_state.*</code>、队列页的 <code>texts.purchase_reason.*</code>。分解界面没有 <code>texts</code> 段。</p><p><code>texts.block_reason.*</code> 与 <code>texts.purchase_reason.*</code> 的键名对应插件内部的拒绝原因键（如 <code>insufficient_materials</code>、<code>station.queue_full</code>、<code>no_price_defined</code>），缺失时会直接显示原始原因键。</p><h2 id="交互约束" tabindex="-1">交互约束 <a class="header-anchor" href="#交互约束" aria-label="Permalink to “交互约束”">​</a></h2><ul><li>所有顶部界面槽位点击都会被取消（不可取走图标），拖拽到顶部界面也会被拦下。</li><li>数字键、副手交换键与不支持的组合键点击会被忽略。</li><li>同一会话内的连点受 <code>gui.click_throttle_ms</code> 节流。</li><li>已打开的界面按 <code>gui.refresh_interval_ticks</code> 定时重绘，玩家的 owner 线程之外不重绘。</li></ul>`,49)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};